"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["80753"],{39575(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios","status":422,"titulo":"RegraCodigo, RegraVersao, FallbackCodigo e Destinos precisam estar todos presentes ou todos ausentes"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["O corpo do pedido de defini\xe7\xe3o de cascata de remanejamento tem uma mistura de\\ncampos presentes e ausentes entre `regraCodigo`, `regraVersao`,\\n`fallbackCodigo` e `destinos`. S\xf3 duas combina\xe7\xf5es s\xe3o v\xe1lidas: os quatro\\nausentes (remove a cascata configurada, se houver) ou os quatro presentes\\n(define uma cascata nova, substituindo a anterior por inteiro). Qualquer\\noutra combina\xe7\xe3o n\xe3o corresponde a nenhuma das duas opera\xe7\xf5es.","Este c\xf3digo tamb\xe9m cobre, separadamente, um item nulo dentro da pr\xf3pria\\nlista `destinos` \u2014 um corpo do pedido malformado que n\xe3o pode desreferenciar\\n`null` e virar erro 500. Nesse caso, o erro vem com o \xedndice do item\\nprefixado (`destinos[2]`, por exemplo) e **acumula**, no mesmo lote, com os\\ndemais erros de item da mesma lista **e** com as causas de fallback\\nausente/inv\xe1lido ou de excesso de origens/destinos, que n\xe3o dependem de os\\nitens serem v\xe1lidos e continuam sendo conferidas mesmo quando algum item \xe9\\ninv\xe1lido demais para participar das confer\xeancias de coer\xeancia entre origens\\n(a causa de lista totalmente vazia n\xe3o entra nesse lote \u2014 havendo ao menos\\num item nulo, a lista j\xe1 n\xe3o est\xe1 vazia). \xc9 diferente da viola\xe7\xe3o de n\xedvel\\nsuperior\\n(mistura entre os quatro campos), que \xe9 sempre um erro isolado, retornado\\nsozinho."],"comoResolver":["Envie os quatro campos preenchidos para definir a cascata, ou os quatro\\nausentes para remov\xea-la. Se o erro veio com um \xedndice de item\\n(`destinos[N]`), remova o item nulo da lista ou preencha seus campos."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);